import { causalityInspector, firewall, Pool, timeline, visualizer } from "@slices/kit";
import { agentHand } from "./slices/agent-hand.js";
import { agentMind } from "./slices/agent-mind.js";
import { agentPort } from "./slices/agent-port.js";
import { apiBook } from "./slices/api-book.js";
import { clipboard } from "./slices/clipboard.js";
import { clock } from "./slices/clock.js";
import { diskControls } from "./slices/disk-controls.js";
import { diskPort } from "./slices/disk-port.js";
import { complianceOracle } from "./slices/compliance-oracle.js";
import { completionOracle } from "./slices/completion-oracle.js";
import { dotMatrix } from "./slices/dot-matrix.js";
import { editorBuffer } from "./slices/editor-buffer.js";
import { editorRenderer } from "./slices/editor-renderer.js";
import { factLog } from "./slices/fact-log.js";
import { foundry } from "./slices/foundry.js";
import { guideBook } from "./slices/guide-book.js";
import { keyboard } from "./slices/keyboard.js";
import { layoutBook } from "./slices/layout-book.js";
import { lockBook } from "./slices/lock-book.js";
import { modelPort } from "./slices/model-port.js";
import { proofingHouse } from "./slices/proofing-house.js";
import { ruleBook } from "./slices/rule-book.js";
import { schemaBook } from "./slices/schema-book.js";
import { sliceToolbar } from "./slices/slice-toolbar.js";
import { stage } from "./slices/stage.js";
import { statusPlate } from "./slices/status-plate.js";
import { syntaxOracle } from "./slices/syntax-oracle.js";
import { thread } from "./slices/thread.js";
import { ticketDesk } from "./slices/ticket-desk.js";
import { ticketRack } from "./slices/ticket-rack.js";
import { threadPlate } from "./slices/thread-plate.js";
import { transportControls } from "./slices/transport-controls.js";
import { workLog } from "./slices/work-log.js";
import { workspaceControls } from "./slices/workspace-controls.js";
// The ignition, and nothing else: a pool, a list of slices, a heartbeat.
// No options, no capabilities, no injected knowledge — every configuration,
// schema, and charter a slice needs arrives as facts on the board, published
// by whichever slice owns it (the stage's charters, the schema-book's law,
// the rule-book's compliance rules). The pool allocates instance ids; the
// pool's own metabolism advances frames. Nothing is whispered.
const pool = new Pool();
pool.mount(stage);
pool.mount(layoutBook);
pool.mount(schemaBook);
pool.mount(lockBook);
pool.mount(firewall);
pool.mount(visualizer);
pool.mount(causalityInspector);
pool.mount(dotMatrix);
pool.mount(statusPlate);
pool.mount(clock);
pool.mount(keyboard);
pool.mount(clipboard);
pool.mount(factLog);
pool.mount(diskPort);
pool.mount(agentPort);
pool.mount(agentHand);
pool.mount(modelPort);
pool.mount(ticketDesk);
pool.mount(agentMind);
pool.mount(proofingHouse);
pool.mount(editorBuffer);
pool.mount(thread);
pool.mount(threadPlate);
pool.mount(workLog);
pool.mount(foundry);
pool.mount(ruleBook);
pool.mount(guideBook);
pool.mount(apiBook);
pool.mount(complianceOracle);
pool.mount(completionOracle);
pool.mount(syntaxOracle);
pool.mount(sliceToolbar);
pool.mount(ticketRack);
pool.mount(editorRenderer);
pool.mount(transportControls);
pool.mount(workspaceControls);
pool.mount(diskControls);
pool.mount(timeline);
pool.run();
